      "codigo_refatorado": "using System;
using UnityEngine;

public class OptimizedEntityScanner : MonoBehaviour
{
    [Header("Configurações")]
    [SerializeField] private float scanRadius = 15f;
    [SerializeField] private LayerMask targetLayer;

    // Buffer estático reutilizável pré-alocado para evitar alocações de array na memória gerenciada
    private static readonly Collider[] hitBuffer = new Collider[64];

    private void Update()
    {
        ScanTargetsNoAlloc();
    }

    private void ScanTargetsNoAlloc()
    {
        // Physics.OverlapSphereNonAlloc preenche o buffer existente em vez de criar um novo array a cada chamada
        int hitCount = Physics.OverlapSphereNonAlloc(transform.position, scanRadius, hitBuffer, targetLayer);

        for (int i = 0; i < hitCount; i++)
        {
            Collider col = hitBuffer[i];
            if (col != null)
            {
                // Processar colisor sem gerar lixo ou boxing
                ProcessCollider(col);
            }
        }
    }

    private void ProcessCollider(Collider target)
    {
        // Implementação sem criação de strings ou novos objetos no heap
    }
}",
      "explicacao_didatica": "O Garbage Collector (coletor de lixo da Unity) precisa pausar a execução do jogo quando a memória acumulada atinge um patamar crítico para limpar objetos descartados. Ao criar arrays ou objetos temporários repetidamente dentro do Update, enchemos a memória muito rápido, forçando o GC a paralisar o jogo por mais de 23 milissegundos para fazer a faxina. Para resolver isso, reutilizamos sempre a mesma gaveta de memória pré-alocada (usando versões NonAlloc das funções da Unity) em vez de comprar gavetas novas a cada fração de segundo."
    }
  ],
